1	import { NextResponse } from "next/server";
2	import { createClient } from "@/lib/supabase/server";
3	import { createAdminClient } from "@/lib/supabase/admin";
4	import { getEffectiveUserId } from "@/lib/simulator";
5	import { applyComputedTransactionAmounts } from "@/lib/cost-items/transaction-amounts";
6	
7	/**
8	 * @swagger
9	 * /api/financials/me:
10	 *   get:
11	 *     summary: Get current user's financial data
12	 *     tags: [Financials]
13	 *     responses:
14	 *       200:
15	 *         description: User's balance and transaction history
16	 *       401:
17	 *         description: Unauthorized
18	 */
19	export async function GET() {
20	  const supabase = await createClient();
21	  const {
22	    data: { user },
23	  } = await supabase.auth.getUser();
24	  if (!user)
25	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
26	
27	  const effectiveUserId = await getEffectiveUserId(user.id);
28	
29	  try {
30	    const adminClient = createAdminClient();
31	
32	    const { data: transactions, error } = await adminClient
33	      .from("financial_transactions")
34	      .select(
35	        "id, user_id, option_id, trip_id, financial_contest_id, type, source, description, amount, method, notes, created_at, trip:trip_settings!financial_transactions_trip_id_fkey(trip_name, trip_year), contest:financial_contests!financial_transactions_financial_contest_id_fkey(name)"
36	      )
37	      .eq("user_id", effectiveUserId)
38	      .order("created_at", { ascending: false });
39	
40	    if (error) {
41	      return NextResponse.json({ error: error.message }, { status: 500 });
42	    }
43	
44	    // Recompute amounts on option-driven transactions from current cost_items.
45	    const recomputed = await applyComputedTransactionAmounts(adminClient, transactions || []);
46	
47	    const formatted = recomputed.map((t) => {
48	      const trip = t.trip as unknown as {
49	        trip_name: string;
50	        trip_year: number;
51	      } | null;
52	      const contest = t.contest as unknown as { name: string } | null;
53	      return {
54	        id: t.id,
55	        trip_id: t.trip_id,
56	        trip_name: trip?.trip_name ?? null,
57	        trip_year: trip?.trip_year ?? null,
58	        financial_contest_id: t.financial_contest_id,
59	        contest_name: contest?.name ?? null,
60	        type: t.type,
61	        source: t.source,
62	        description: t.description,
63	        amount: Number(t.amount),
64	        method: t.method,
65	        notes: t.notes,
66	        created_at: t.created_at,
67	      };
68	    });
69	
70	    let totalCharges = 0;
71	    let totalPayments = 0;
72	    for (const t of formatted) {
73	      if (t.type === "charge") {
74	        totalCharges += t.amount;
75	      } else if (t.type === "payment") {
76	        totalPayments += t.amount;
77	      }
78	    }
79	
80	    return NextResponse.json({
81	      balance: {
82	        total_charges: Math.round(totalCharges * 100) / 100,
83	        total_payments: Math.round(totalPayments * 100) / 100,
84	        balance: Math.round((totalPayments - totalCharges) * 100) / 100,
85	      },
86	      transactions: formatted,
87	    });
88	  } catch (error) {
89	    console.error("Financials me error:", error);
90	    return NextResponse.json(
91	      { error: "Internal server error" },
92	      { status: 500 }
93	    );
94	  }
95	}
