42	    const recomputed = await applyComputedTransactionAmounts(adminClient, txnResult.data || []);
43	
44	    // Build map: transaction_id -> most recent editor (first entry per txn since sorted desc)
45	    const lastEditorMap = new Map<string, { name: string; has_history: boolean }>();
46	    for (const h of historyResult.data || []) {
47	      if (!lastEditorMap.has(h.transaction_id)) {
48	        const changerName = (h.changer as unknown as { display_name: string } | null)?.display_name ?? null;
49	        lastEditorMap.set(h.transaction_id, {
