1	// Recompute the displayed amount on option-driven financial_transactions.
2	//
3	// `financial_transactions.amount` is set at insert time and never updated.
4	// Once cost_items became the source of truth for option prices (#125 Phase 3),
5	// the stored amount can drift any time admin edits a linked cost_item — the
6	// user's selection is unchanged but the price isn't. This helper derives the
7	// CURRENT amount per (user, option_id) pair so balances and ledgers display
8	// the live cost regardless of when the transaction was recorded.
9	//
10	// Apply this at the API boundary anywhere transactions are read for display
11	// or aggregation:
12	//   /api/admin/financials/balances   (recompute then sum)
13	//   /api/admin/financials/ledger
14	//   /api/admin/financials/transactions
15	//   /api/admin/financials/contest-ledger
16	//   /api/admin/financials/summary
17	//   /api/financials/me               (Loozer-facing)
18	
19	import type { SupabaseClient } from "@supabase/supabase-js";
20	import { computeOptionCosts, type OptionLike } from "@/lib/cost-items/compute";
21	
22	// eslint-disable-next-line @typescript-eslint/no-explicit-any
23	type Client = SupabaseClient<any, "public", any>;
24	
25	export interface TransactionLike {
26	  user_id: string;
27	  source: string;
28	  option_id: string | null;
29	  amount: number;
30	  // Other fields are passed through unchanged.
31	  [k: string]: unknown;
32	}
33	
34	/**
35	 * Replace `amount` on every `source='option'` transaction with the value
36	 * computed from the user's CURRENT selection on that option, using the
37	 * option's CURRENT cost (derived from cost_items via computeOptionCosts).
38	 *
39	 * Returns a new array of transactions; input is not mutated.
40	 *
41	 * Behavior:
42	 *   - non-option transactions are passed through untouched
43	 *   - if no current selection exists for that (user, option), the stored
44	 *     amount is preserved as a fallback (this should be rare; the selections
45	 *     API deletes the transaction when the user clears their selection)
46	 *   - if the option has been deleted, the stored amount is preserved
47	 *
48	 * Performance: 2 bulk queries (options + selections) + 1 cost-item bulk query
49	 * inside computeOptionCosts. Independent of transactions.length.
50	 */
51	export async function applyComputedTransactionAmounts<T extends TransactionLike>(
52	  client: Client,
53	  transactions: T[],
54	): Promise<T[]> {
55	  if (!transactions || transactions.length === 0) return transactions;
56	
57	  const optionTxs = transactions.filter(
58	    (t) => t.source === "option" && t.option_id,
59	  );
60	  if (optionTxs.length === 0) return transactions;
61	
62	  const optionIds = [...new Set(optionTxs.map((t) => t.option_id as string))];
63	  const userIds = [...new Set(optionTxs.map((t) => t.user_id))];
64	
65	  const [{ data: rawOptions }, { data: selections }] = await Promise.all([
66	    client.from("trip_options").select("*").in("id", optionIds),
67	    client
68	      .from("user_option_selections")
69	      .select("user_id, option_id, value")
70	      .in("user_id", userIds)
71	      .in("option_id", optionIds),
72	  ]);
73	
74	  // computeOptionCosts overlays each option's cost / per-choice cost from
75	  // its linked cost_items.
76	  const options = await computeOptionCosts(client, (rawOptions || []) as OptionLike[]);
77	  const optionById = new Map(options.map((o) => [o.id, o]));
78	  const selByKey = new Map<string, unknown>();
79	  for (const s of (selections || []) as Array<{ user_id: string; option_id: string; value: unknown }>) {
80	    selByKey.set(`${s.user_id}|${s.option_id}`, s.value);
81	  }
82	
83	  return transactions.map((tx) => {
84	    if (tx.source !== "option" || !tx.option_id) return tx;
85	    const opt = optionById.get(tx.option_id);
86	    if (!opt) return tx;
87	    const sel = selByKey.get(`${tx.user_id}|${tx.option_id}`);
88	    if (sel === undefined || sel === null) return tx;
89	
90	    const computed = computeAmountFromSelection(opt, sel);
91	    if (computed === null) return tx;
92	
93	    // Only override if the value actually differs (preserves identity for
94	    // most rows, useful for debugging).
95	    if (Number(tx.amount) === computed) return tx;
96	    return { ...tx, amount: computed };
97	  });
98	}
99	
100	function computeAmountFromSelection(
101	  option: OptionLike,
102	  value: unknown,
103	): number | null {
104	  if (option.option_type === "checkbox") {
105	    if (value !== true) return null;
106	    const c = Number(option.cost ?? 0);
107	    return c > 0 ? c : null;
108	  }
109	  if (option.option_type === "select") {
110	    const matched = (option.choices || []).find((c) => c.value === value);
111	    if (!matched || matched.cost == null) return null;
112	    const n = Number(matched.cost);
113	    return n > 0 ? n : null;
114	  }
115	  if (option.option_type === "multi_select") {
116	    const arr = Array.isArray(value) ? (value as string[]) : [];
117	    let total = 0;
118	    for (const v of arr) {
119	      const matched = (option.choices || []).find((c) => c.value === v);
120	      if (matched?.cost) total += Number(matched.cost);
121	    }
122	    return total > 0 ? total : null;
123	  }
124	  return null;
125	}
