3	import { useState, useEffect, useCallback, useMemo } from "react";
4	import Link from "next/link";
5	
6	type TransactionSource =
7	  | "option"
8	  | "manual"
9	  | "adjustment"
10	  | "contest_entry"
11	  | "deposit"
12	  | "withdrawal"
13	  | "winnings"
14	  | "credit"
15	  | "expense";
16	
17	interface Transaction {
18	  id: string;
19	  trip_id: string | null;
20	  trip_name: string | null;
21	  trip_year: number | null;
22	  financial_contest_id: string | null;
23	  contest_name: string | null;
24	  type: "charge" | "payment";
25	  source: TransactionSource;
26	  description: string;
27	  amount: number;
28	  method: string | null;
29	  notes: string | null;
30	  created_at: string;
31	}
32	
33	interface FinancialData {
34	  balance: {
35	    total_charges: number;
36	    total_payments: number;
37	    balance: number;
38	  };
39	  transactions: Transaction[];
40	}
41	
42	// Category label + color for each source. `option` intentionally omitted — the
43	// description ("Breakfast", "Green fees", etc.) already tells you what it is.
44	// `manual` is also omitted: legacy `manual` payments are treated as deposits
45	// via effectiveSource() below; manual charges render without a pill.
46	const CATEGORY: Partial<Record<TransactionSource, { label: string; className: string }>> = {
