85	function startOfRange(range: DateRangeValue): Date | null {
86	  const now = new Date();
87	  if (range === "all") return null;
88	  if (range === "30d") {
89	    const d = new Date(now);
90	    d.setDate(d.getDate() - 30);
91	    return d;
92	  }
93	  if (range === "90d") {
94	    const d = new Date(now);
95	    d.setDate(d.getDate() - 90);
96	    return d;
97	  }
98	  if (range === "ytd") return new Date(now.getFullYear(), 0, 1);
99	  return null;
100	}
