1	import { NextResponse } from "next/server";
2	import { createClient } from "@/lib/supabase/server";
3	import { createAdminClient } from "@/lib/supabase/admin";
4	import { syncContestEnrollment, syncCostItemContestEnrollment } from "@/lib/option-contest-sync";
5	import { getEffectiveUserId } from "@/lib/simulator";
6	import { computeOptionCosts } from "@/lib/cost-items/compute";
