39	export async function GET(request: Request) {
40	  const supabase = await createClient();
41	  const { data: { user } } = await supabase.auth.getUser();
42	  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
43	
44	  const effectiveUserId = await getEffectiveUserId(user.id);
45	
46	  const { searchParams } = new URL(request.url);
47	  const tripId = searchParams.get("trip_id");
48	  if (!tripId) return NextResponse.json({ error: "trip_id is required" }, { status: 400 });
49	
50	  const adminClient = createAdminClient();
51	  const { data, error } = await adminClient
52	    .from("user_option_selections")
53	    .select("*")
54	    .eq("trip_id", tripId)
55	    .eq("user_id", effectiveUserId);
56	
57	  if (error) return NextResponse.json({ error: error.message }, { status: 500 });
58	
59	  // Build a map keyed by option_id
60	  const selections: Record<string, { id: string; value: unknown }> = {};
61	  for (const row of data || []) {
62	    selections[row.option_id] = { id: row.id, value: row.value };
63	  }
64	
65	  return NextResponse.json({ selections });
66	}
