68	export async function PUT(request: Request) {
69	  const supabase = await createClient();
70	  const { data: { user } } = await supabase.auth.getUser();
71	  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
72	
73	  const effectiveUserId = await getEffectiveUserId(user.id);
74	
75	  const { trip_id, option_id, value: rawValue } = await request.json();
76	  if (!trip_id || !option_id) {
77	    return NextResponse.json({ error: "trip_id and option_id are required" }, { status: 400 });
78	  }
79	
80	  const adminClient = createAdminClient();
81	
82	  // Deadline enforcement
83	  const { data: settings, error: settingsError } = await adminClient
84	    .from("trip_option_settings")
85	    .select("*")
86	    .eq("trip_id", trip_id)
87	    .maybeSingle();
88	
89	  if (settingsError) return NextResponse.json({ error: settingsError.message }, { status: 500 });
90	
91	  if (settings) {
92	    if (settings.is_open === false) {
93	      return NextResponse.json({ error: "Selections are closed" }, { status: 403 });
94	    }
95	    if (settings.selection_deadline && new Date() > new Date(settings.selection_deadline)) {
96	      return NextResponse.json({ error: "Selection deadline has passed" }, { status: 403 });
97	    }
98	  }
99	
100	  // Load the option upfront so we can validate quantity-shaped values
101	  const { data: rawOption, error: optionError } = await adminClient
102	    .from("trip_options")
103	    .select("*")
104	    .eq("id", option_id)
105	    .single();
106	  if (optionError) return NextResponse.json({ error: optionError.message }, { status: 500 });
107	
108	  // Replace stored cost with the value computed from linked cost_items so the
109	  // charge we record matches what the user saw on the options page.
110	  const [option] = await computeOptionCosts(adminClient, [rawOption]);
111	
112	  let value = rawValue;
113	  if (option.option_type === "quantity" && rawValue != null) {
114	    const normalized = normalizeQuantityValue(rawValue, option);
115	    if (normalized.error) {
116	      return NextResponse.json({ error: normalized.error }, { status: 400 });
117	    }
118	    value = normalized.value;
119	  }
120	
121	  // 1. Upsert or delete the selection
122	  if (value === null || value === undefined) {
123	    const { error: delError } = await adminClient
124	      .from("user_option_selections")
125	      .delete()
126	      .eq("user_id", effectiveUserId)
127	      .eq("option_id", option_id);
128	    if (delError) return NextResponse.json({ error: delError.message }, { status: 500 });
129	  } else {
130	    const { error: upsertError } = await adminClient
131	      .from("user_option_selections")
132	      .upsert(
133	        { trip_id, user_id: effectiveUserId, option_id, value },
134	        { onConflict: "user_id,option_id" }
135	      );
136	    if (upsertError) return NextResponse.json({ error: upsertError.message }, { status: 500 });
137	  }
138	
139	  // 2. Sync financial charges — always delete existing option-sourced charges first
140	  const { error: deleteChargeError } = await adminClient
141	    .from("financial_transactions")
142	    .delete()
143	    .eq("user_id", effectiveUserId)
144	    .eq("option_id", option_id)
145	    .eq("source", "option");
146	  if (deleteChargeError) return NextResponse.json({ error: deleteChargeError.message }, { status: 500 });
147	
148	  // If value is null (deletion), cascade-clear dependent options, sync contest enrollment, and we're done
149	  if (value === null || value === undefined) {
150	    await Promise.all([
151	      syncContestEnrollment(adminClient, effectiveUserId, option, null),
152	      syncCostItemContestEnrollment(adminClient, effectiveUserId, option_id, null),
153	    ]);
154	
155	    // Find options that depend on this one and clear their selections too
156	    const { data: dependents } = await adminClient
157	      .from("trip_options")
158	      .select("id, option_type, linked_contest_id, choices")
159	      .eq("depends_on_option_id", option_id);
160	
161	    if (dependents && dependents.length > 0) {
162	      const depIds = dependents.map((d) => d.id);
163	      // Batch delete selections and charges for all dependents
164	      await Promise.all([
165	        adminClient
166	          .from("user_option_selections")
167	          .delete()
168	          .eq("user_id", effectiveUserId)
169	          .in("option_id", depIds),
170	        adminClient
171	          .from("financial_transactions")
172	          .delete()
173	          .eq("user_id", effectiveUserId)
174	          .in("option_id", depIds)
175	          .eq("source", "option"),
176	        // Unenroll from each dependent's contest (can't batch — each has different contest_id)
177	        ...dependents.flatMap((dep) => [
178	          syncContestEnrollment(adminClient, effectiveUserId, dep, null),
179	          syncCostItemContestEnrollment(adminClient, effectiveUserId, dep.id, null),
180	        ]),
181	      ]);
182	    }
