1	/**
2	 * Pickem-specific payout computation. Uses percentages from
3	 * `contests.payout_splits` (the unified payout-splits store, issue #124),
4	 * rounds each place down to the nearest $5, then redistributes the
5	 * leftover $5 chunks starting from the highest place (so 1st gets the
6	 * benefit of any rounding remainder).
7	 *
8	 * Single source for both:
9	 *   - `materializePickemWinners` (writes contest_winners.amount)
10	 *   - `PickemManager` admin UI (renders the preview alongside the
11	 *     splits editor)
12	 *
13	 * Storage shape on `contests.payout_splits`:
14	 *   `[{place: 1, kind: "percentage", amount: 50}, ...]`
15	 * where `amount` is the percentage (0–100).
16	 */
17	
18	import type { PayoutSplit } from "@/lib/payout-events/splits";
19	
20	export interface PickemPayout {
21	  place: number;
22	  percentage: number;
23	  amount: number;
24	}
25	
26	const PICKEM_ROUND_TO = 5;
27	
28	export function computePickemPayouts(
29	  totalPot: number,
30	  splits: PayoutSplit[] | null | undefined,
31	): PickemPayout[] {
32	  if (!Number.isFinite(totalPot) || totalPot <= 0) return [];
33	  if (!splits || splits.length === 0) return [];
34	
35	  // Pull percentages from the splits config. Anything that isn't a
36	  // percentage entry is ignored — Pickem's payouts are percentage-based
37	  // by convention.
38	  const percents = splits
39	    .filter((s) => s.kind === "percentage")
40	    .map((s) => ({
41	      place: s.place,
42	      percentage: Math.max(0, Math.min(100, Number(s.amount) || 0)),
43	    }))
44	    .sort((a, b) => a.place - b.place);
45	  if (percents.length === 0) return [];
46	
47	  // Floor each place down to the nearest $PICKEM_ROUND_TO.
48	  const results = percents.map((p) => ({
49	    place: p.place,
50	    percentage: p.percentage,
51	    amount:
52	      Math.floor((totalPot * p.percentage) / 100 / PICKEM_ROUND_TO) *
53	      PICKEM_ROUND_TO,
54	  }));
55	
56	  // Distribute the remainder ($PICKEM_ROUND_TO chunks) starting from
57	  // place 1 — higher places benefit from rounding leftovers.
58	  const allocated = results.reduce((sum, r) => sum + r.amount, 0);
59	  let remaining = Math.max(0, totalPot - allocated);
60	  for (const r of results) {
61	    if (remaining >= PICKEM_ROUND_TO) {
62	      r.amount += PICKEM_ROUND_TO;
63	      remaining -= PICKEM_ROUND_TO;
64	    } else {
65	      break;
66	    }
67	  }
68	  return results;
69	}
