7	// contest_entry) are written by their own subsystems; 'manual' and
8	// 'adjustment' remain legal so legacy flows / bookkeeping fixes still work.
9	const ADMIN_SOURCES = [
10	  "deposit",
11	  "withdrawal",
12	  "winnings",
13	  "credit",
14	  "expense",
15	  "manual",
16	  "adjustment",
17	] as const;
18	type AdminSource = (typeof ADMIN_SOURCES)[number];
19	
20	const SOURCE_REQUIRED_TYPE: Partial<Record<AdminSource, "charge" | "payment">> = {
21	  deposit: "payment",
22	  winnings: "payment",
23	  credit: "payment",
24	  withdrawal: "charge",
25	  expense: "charge",
