1	import { NextResponse } from "next/server";
2	import { createAdminClient } from "@/lib/supabase/admin";
3	import { checkPermissionAccess } from "@/lib/permissions-server";
4	
5	/**
6	 * @swagger
7	 * /api/admin/financials/payout-grid/cell:
8	 *   put:
9	 *     summary: Toggle paid status for a single Loozer × event cell
10	 *     tags: [Admin]
11	 *     description: |
12	 *       Body: `{ user_id, event_key, paid }`.
13	 *       Writes `contest_winners.paid` for the matching contest's row.
14	 */
15	export async function PUT(request: Request) {
16	  const admin = await checkPermissionAccess("manage_finances");
17	  if (!admin) {
18	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
19	  }
20	
21	  const body = await request.json();
22	  const { user_id, event_key, paid, pickem_contest_id } = body;
23	  if (!user_id || !event_key || typeof paid !== "boolean") {
24	    return NextResponse.json(
25	      { error: "user_id, event_key, and paid are required" },
26	      { status: 400 },
27	    );
28	  }
29	
30	  const adminClient = createAdminClient();
31	
32	  // Resolve event_key (payout_sheet_events.id) to a contest_id.
33	  // pickem_contest_id is accepted as a fallback for callers that pass
34	  // the contest directly.
35	  const { data: row } = await adminClient
36	    .from("payout_sheet_events")
37	    .select("contest_id")
38	    .eq("id", event_key)
39	    .single();
40	  const contestId = row?.contest_id || pickem_contest_id || null;
41	  if (!contestId) {
42	    return NextResponse.json(
43	      { error: "Event has no linked contest; can't toggle paid status." },
44	      { status: 400 },
45	    );
46	  }
47	
48	  const { error: cwErr } = await adminClient
49	    .from("contest_winners")
50	    .update({
51	      paid,
52	      paid_at: paid ? new Date().toISOString() : null,
53	      paid_by: paid ? admin.id : null,
54	    })
55	    .eq("contest_id", contestId)
56	    .eq("user_id", user_id);
57	  if (cwErr) return NextResponse.json({ error: cwErr.message }, { status: 500 });
58	
59	  return NextResponse.json({ success: true });
60	}
