1	/**
2	 * Issue #124 — unified Winners-grid loader. Replaces the per-kind
3	 * dispatch in `grid.ts` with a single read from `contest_winners`.
4	 *
5	 * Flow:
6	 *   1. Load the payout sheet (rows + their contest data).
7	 *   2. Lazy-materialize each contest-linked row's winners (so the table
8	 *      always reflects the current scoring state).
9	 *   3. Read `contest_winners` for those contests in one query.
10	 *   4. Build cells: one per (user_id, event_id) where contest_winners has
11	 *      a row. Amount and paid come straight from `contest_winners`.
12	 */
13	
14	import type { SupabaseClient } from "@supabase/supabase-js";
15	import { loadPayoutSheet } from "./compute";
16	import { materializeContestWinners } from "@/lib/winners/materialize";
17	
18	// eslint-disable-next-line @typescript-eslint/no-explicit-any
19	type Client = SupabaseClient<any, "public", any>;
20	
21	export interface GridLoozer {
22	  user_id: string;
23	  display_name: string;
24	  avatar_url: string | null;
25	}
26	
27	export interface GridEvent {
28	  key: string;
29	  label: string;
30	  sort_order: number;
31	  is_payout: boolean;
32	  total: number;
33	  pickem: boolean;
34	}
35	
36	export interface GridCell {
37	  user_id: string;
38	  event_key: string;
39	  amount: number;
40	  paid: boolean;
41	}
42	
43	export interface GridData {
44	  loozers: GridLoozer[];
45	  events: GridEvent[];
46	  cells: GridCell[];
47	}
48	
49	export async function loadPayoutGridV2(
50	  client: Client,
51	  tripId: string,
52	): Promise<GridData> {
53	  const sheet = await loadPayoutSheet(client, tripId);
54	
55	  // Lazy-materialize: re-derive winners for every contest-linked row.
56	  // Cheap operations (a few queries per contest) — acceptable on grid
57	  // load. Fan out in parallel.
58	  const contestIds = sheet
59	    .filter((r) => r.contest_id)
60	    .map((r) => r.contest_id as string);
61	  await Promise.all(
62	    contestIds.map((id) =>
63	      materializeContestWinners(client, id).catch((err) => {
64	        console.error(`materializeContestWinners(${id}) failed:`, err);
65	      }),
66	    ),
67	  );
68	
69	  // Load attendees for the loozers axis.
70	  const { data: rosterRows } = await client
71	    .from("event_participants")
72	    .select(
73	      "user:users!event_participants_user_id_fkey(id, display_name, avatar_url, is_system, is_financial_only)",
74	    )
75	    .eq("trip_id", tripId)
76	    .eq("on_roster", true);
77	
78	  type UserShape = {
79	    id: string;
80	    display_name: string;
81	    avatar_url: string | null;
82	    is_system?: boolean;
83	    is_financial_only?: boolean;
84	  };
85	
86	  const loozers: GridLoozer[] = (rosterRows || [])
87	    .map((r) => {
88	      const u = (r as { user: UserShape | UserShape[] | null }).user;
89	      return Array.isArray(u) ? u[0] ?? null : u;
90	    })
91	    .filter((u): u is UserShape => !!u && !u.is_system && !u.is_financial_only)
92	    .map((u) => ({
93	      user_id: u.id,
94	      display_name: u.display_name,
95	      avatar_url: u.avatar_url ?? null,
96	    }))
97	    .sort((a, b) => a.display_name.localeCompare(b.display_name));
98	
99	  // Pull every winner row across all linked contests in one query.
100	  const winnersByContest = new Map<
101	    string,
102	    Array<{ user_id: string; place: number; amount: number | null; paid: boolean }>
103	  >();
104	  if (contestIds.length > 0) {
105	    const { data: winners } = await client
106	      .from("contest_winners")
107	      .select("contest_id, user_id, place, amount, paid")
108	      .in("contest_id", contestIds);
109	    for (const w of winners || []) {
110	      if (!winnersByContest.has(w.contest_id)) winnersByContest.set(w.contest_id, []);
111	      winnersByContest.get(w.contest_id)!.push({
112	        user_id: w.user_id,
113	        place: w.place,
114	        amount: w.amount === null ? 0 : Number(w.amount),
115	        paid: !!w.paid,
116	      });
117	    }
118	  }
119	
120	  const events: GridEvent[] = [];
121	  const cells: GridCell[] = [];
122	  for (const row of sheet) {
123	    events.push({
124	      key: row.id,
125	      label: row.label,
126	      sort_order: row.sort_order,
127	      is_payout: row.is_payout,
128	      total: row.total,
129	      // Pickem column is rendered specially in the UI (separate paid
130	      // checkbox path historically). We preserve that flag for now so
131	      // the existing UI keeps rendering correctly.
132	      pickem: row.contest?.contest_type === "pickem",
133	    });
134	    if (!row.contest_id) continue;
135	    const winners = winnersByContest.get(row.contest_id) || [];
136	    for (const w of winners) {
137	      cells.push({
138	        user_id: w.user_id,
139	        event_key: row.id,
140	        amount: w.amount ?? 0,
141	        paid: w.paid,
142	      });
143	    }
144	  }
145	
146	  return { loozers, events, cells };
147	}
