40	    // Deduplicate by user_id (a user could appear multiple times)
41	    const userMap = new Map<string, { id: string; display_name: string; full_name: string; avatar_url: string | null }>();
42	    for (const p of participants) {
43	      const u = p.user as unknown as { id: string; display_name: string; full_name: string; avatar_url: string | null } | null;
44	      if (u && !userMap.has(p.user_id)) {
